	@ParameterizedTest
	@MethodSource("codecs")
	void incrementalReaderPreservesConcatenatedFrameBoundaries(BulkCodec codec) throws Exception {
		Path file = temporaryDirectory.resolve("frames-" + codec.token() + ".bin");
		writeFrame(file, codec, 11);
		if (codec.kind() != BulkCodec.Kind.NONE) {
			writeFrame(file, codec);
		}
		writeFrame(file, codec, 29);

		try (BulkLz4.ConcatenatedFrames frames = BulkLz4.openConcatenated(file, codec)) {
			assertThat(frames.nextFrame()).isTrue();
			assertThat(frames.frame().readInt()).isEqualTo(11);
			if (codec.kind() == BulkCodec.Kind.NONE) {
				assertThat(frames.frame().readInt()).isEqualTo(29);
				assertThat(frames.frame().read()).isEqualTo(-1);
				assertThat(frames.nextFrame()).isFalse();
				return;
			}
			assertThat(frames.frame().read()).isEqualTo(-1);
			assertThat(frames.nextFrame()).isTrue();
			assertThat(frames.frame().read()).isEqualTo(-1);
			assertThat(frames.nextFrame()).isTrue();
			assertThat(frames.frame().readInt()).isEqualTo(29);
			assertThat(frames.frame().read()).isEqualTo(-1);
			assertThat(frames.nextFrame()).isFalse();
		}
	}

