	@Test
	void schedulerAwareCursorBorrowsAnAtomicInputAndDescriptorLease() throws Exception {
		Path file = temporaryDirectory.resolve("leased-input.bin");
		writeFrame(file, BulkCodec.FAST, 41, 43);
		long inputMemory = BulkLz4.concatenatedInputMemoryBytes(BulkCodec.FAST);
		try (BulkTaskScheduler scheduler = new BulkTaskScheduler(1, inputMemory, 1)) {
			BulkTaskScheduler.ResourceLease lease = scheduler.reserveBlocking(inputMemory, 1);
			try {
				try (BulkTaskScheduler.FileDescriptorScope scope = scheduler.bindFileDescriptorLease(lease);
						BulkLz4.ConcatenatedFrames frames = BulkLz4.openConcatenated(file, BulkCodec.FAST, scheduler)) {
					assertThatThrownBy(() -> scheduler.bindFileDescriptorLease(lease))
							.isInstanceOf(IllegalStateException.class);
					assertThat(scheduler.reservedMemoryBytes()).isEqualTo(inputMemory);
					assertThat(scheduler.reservedFileDescriptors()).isEqualTo(1);
					assertThat(scheduler.peakOpenFileHandles()).isEqualTo(1);
					assertThat(frames.nextFrame()).isTrue();
					assertThat(frames.frame().readInt()).isEqualTo(41);
					assertThat(frames.frame().readInt()).isEqualTo(43);
				}
				assertThat(scheduler.reservedMemoryBytes()).isEqualTo(inputMemory);
				assertThat(scheduler.reservedFileDescriptors()).isEqualTo(1);
			} finally {
				lease.close();
			}
			assertThat(scheduler.reservedMemoryBytes()).isZero();
			assertThat(scheduler.reservedFileDescriptors()).isZero();
		}
	}

