	private static void writeFrame(Path file, BulkCodec codec, int... values) throws IOException {
		try (DataOutputStream output = BulkLz4.appendOutput(file, codec)) {
			for (int value : values) {
				output.writeInt(value);
			}
		}
	}

	private static void drainFrames(Path file, BulkCodec codec) throws IOException {
		try (BulkLz4.ConcatenatedFrames frames = BulkLz4.openConcatenated(file, codec)) {
			while (frames.nextFrame()) {
				frames.frame().readAllBytes();
			}
		}
	}
